function reportEditor(item={}){
  let social=parseReportSocial(item);if(!social.length)social=[{platform:'Instagram',profile:'',followers:'',reach:'',views:'',interactions:'',profile_visits:'',clicks:'',leads:''}];
  const body=`<form id="reportForm"><div class="form-grid">${fieldHtml('client_id','Cliente','client',item.client_id)}${fieldHtml('period','Periodo','month',item.period||today().slice(0,7))}${fieldHtml('title','Titolo report','text',item.title||'Report risultati social',1)}${fieldHtml('contents','Contenuti pubblicati','number',item.contents||0)}<div class="field span-2"><label>Risultati dei profili social</label><div id="reportSocialRows"></div><button type="button" class="btn btn-ghost" id="addReportSocial" style="margin-top:10px">＋ Aggiungi profilo</button></div>${fieldHtml('worked','Attività effettuate','textarea',item.worked||'',1)}${fieldHtml('wins','Cosa ha funzionato','textarea',item.wins||'',1)}${fieldHtml('improve','Cosa migliorare','textarea',item.improve||'',1)}${fieldHtml('next_strategy','Strategia / prossime azioni','textarea',item.next_strategy||'',1)}</div></form>`;
  modal(item.id?'Modifica report':'Nuovo report',body,async()=>{
    const data=Object.fromEntries(new FormData($('#reportForm')).entries());
    const rows=$$('.report-social-row').map(r=>({platform:$('[name=platform]',r).value,profile:$('[name=profile]',r).value,followers:Number($('[name=followers]',r).value||0),reach:Number($('[name=reach]',r).value||0),views:Number($('[name=views]',r).value||0),interactions:Number($('[name=interactions]',r).value||0),profile_visits:Number($('[name=profile_visits]',r).value||0),clicks:Number($('[name=clicks]',r).value||0),leads:Number($('[name=leads]',r).value||0)}));
    data.social_results_json=JSON.stringify(rows);data.followers=rows.reduce((s,x)=>s+x.followers,0);data.reach=rows.reduce((s,x)=>s+x.reach,0);data.views=rows.reduce((s,x)=>s+x.views,0);data.interactions=rows.reduce((s,x)=>s+x.interactions,0);data.leads=rows.reduce((s,x)=>s+x.leads,0);data.cpl=0;data.ad_spend=0;
    try{if(item.id)await api('/api/data/reports/'+item.id,{method:'PUT',body:JSON.stringify(data)});else await api('/api/data/reports',{method:'POST',body:JSON.stringify(data)});closeModal();reportsPage();toast('Report salvato')}catch(e){toast(e.message)}
  });
  const render=()=>{const el=$('#reportSocialRows');el.innerHTML=social.map((x,i)=>`<div class="report-social-row"><select class="select" name="platform">${['Instagram','Facebook','TikTok','LinkedIn','YouTube','Google Business','Altro'].map(p=>`<option ${p===x.platform?'selected':''}>${p}</option>`).join('')}</select><input class="input" name="profile" placeholder="Profilo / pagina" value="${esc(x.profile||'')}"><input class="input" name="followers" type="number" min="0" placeholder="Follower" value="${x.followers??''}"><input class="input" name="reach" type="number" min="0" placeholder="Reach" value="${x.reach??''}"><input class="input" name="views" type="number" min="0" placeholder="Views" value="${x.views??''}"><input class="input" name="interactions" type="number" min="0" placeholder="Interazioni" value="${x.interactions??''}"><input class="input" name="profile_visits" type="number" min="0" placeholder="Visite profilo" value="${x.profile_visits??''}"><input class="input" name="clicks" type="number" min="0" placeholder="Click" value="${x.clicks??''}"><input class="input" name="leads" type="number" min="0" placeholder="Lead" value="${x.leads??''}"><button type="button" class="xbtn removeReportSocial" data-i="${i}">×</button></div>`).join('');$$('.removeReportSocial').forEach(b=>b.onclick=()=>{social.splice(Number(b.dataset.i),1);if(!social.length)social.push({platform:'Instagram'});render()})};
  render();$('#addReportSocial').onclick=()=>{social.push({platform:'Instagram'});render()};
}
function clientStatsPanel(c){
  if(!c)return '<div class="card empty">Seleziona un cliente per vedere le statistiche.</div>';
  const monthlyRows=(c.monthly||[]).map(m=>`<tr><td>${esc(m.month)}</td><td>${fmtEUR(m.revenue)}</td><td>${fmtEUR(m.expense)}</td><td>${fmtEUR(Number(m.revenue)-Number(m.expense))}</td></tr>`).join('');
  return `<div class="grid grid-kpi" style="margin-top:16px">${kpi('Canone mensile',fmtEUR(c.monthlyValue),'Pacchetto attuale')}${kpi('Valore pacchetto anno',fmtEUR(c.annualRecurring),'Mensilità del pacchetto nell’anno corrente')}${kpi('Da mese corrente a fine anno',fmtEUR(c.remainingYearValue),'Valore teorico del periodo residuo')}${kpi('Incassato',fmtEUR(c.actualIncome),'Entrate registrate')}${kpi('Uscite attribuite',fmtEUR(c.actualExpense),'Costi del cliente')}${kpi('Netto registrato',fmtEUR(c.netActual),'Entrate meno uscite')}${kpi('Da incassare',fmtEUR(c.paymentsPending),'Pagamenti aperti')}</div>
  <div class="grid two-col" style="margin-top:16px"><div class="card"><div class="section-title"><div><h2>Situazione economica</h2><span>${esc(c.name)}</span></div></div><div class="finance-detail-grid"><div><span>Fatture emesse</span><b>${fmtEUR(c.invoiceIssued)}</b></div><div><span>Fatture pagate</span><b>${fmtEUR(c.invoicePaid)}</b></div><div><span>Pagamenti confermati</span><b>${fmtEUR(c.paymentsPaid)}</b></div><div><span>Scaduto / insoluto</span><b>${fmtEUR(c.overduePayments)}</b></div><div><span>Valore pacchetto anno corrente</span><b>${fmtEUR(c.annualRecurring)}</b></div><div><span>Valore 12 mesi pieno</span><b>${fmtEUR(c.fullYearValue)}</b></div><div><span>Periodo pacchetto</span><b>${c.packageStart?fmtDate(c.packageStart):'—'} → ${c.packageEnd?fmtDate(c.packageEnd):'Aperto'}</b></div></div></div><div class="card"><div class="section-title"><div><h2>Pacchetto cliente</h2><span>Configurazione attiva</span></div></div><div class="metric-row"><div class="metric"><b>${c.social?.posts||0}</b><span>post / mese</span></div><div class="metric"><b>${c.social?.reels||0}</b><span>reel / mese</span></div><div class="metric"><b>${c.social?.stories||0}</b><span>storie / mese</span></div><div class="metric"><b>${c.social?.total||0}</b><span>contenuti previsti</span></div></div><div class="small muted" style="margin-top:18px">Servizi: ${(c.services||[]).map(esc).join(' · ')||'Nessun servizio configurato'}</div></div></div>
  <div class="card" style="margin-top:16px"><div class="section-title"><div><h2>Andamento economico</h2><span>Ultimi 12 mesi</span></div></div><div class="table-wrap"><table class="table client-month-table"><thead><tr><th>Mese</th><th>Entrate</th><th>Uscite</th><th>Netto</th></tr></thead><tbody>${monthlyRows}</tbody></table></div></div>`;
}
async function analyticsPage(){
  const d=await api('/api/analytics');
  const list=d.clientStats||[];
  const first=list.find(x=>x.status==='Attivo')||list[0];
  $('#content').innerHTML=`<div class="page-head"><div><h1>Statistiche clienti</h1><p>Analisi economica personalizzata per ogni cliente EFFE, alimentata da pagamenti, fatture e pacchetto.</p></div><div class="client-stat-select"><label>Cliente</label><select class="select" id="analyticsClient">${list.map(c=>`<option value="${c.id}" ${String(c.id)===String(first?.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>
  <div class="grid portfolio-kpis">${kpi('Clienti attivi',d.activeClients,'Portafoglio EFFE')}${kpi('MRR agenzia',fmtEUR(d.mrr),'Ricavi ricorrenti previsti')}${kpi('Valore pacchetti anno',fmtEUR(d.annualProjection),'Tutte le mensilità previste nell’anno corrente')}${kpi('Da mese corrente a fine anno',fmtEUR(d.remainingYearProjection),'Valore teorico dei pacchetti ancora nel periodo')}${kpi('Netto registrato',fmtEUR(d.actualNet),'Movimenti EFFE attribuiti')}</div>
  <div class="client-switcher">${list.map(c=>`<button class="client-chip ${String(c.id)===String(first?.id)?'active':''}" data-client="${c.id}"><span>${esc(c.name)}</span><b>${fmtEUR(c.remainingYearValue)} fino a fine anno</b></button>`).join('')}</div><div id="clientAnalyticsDetail">${clientStatsPanel(first)}</div>`;
  const show=id=>{const c=list.find(x=>String(x.id)===String(id));$('#clientAnalyticsDetail').innerHTML=clientStatsPanel(c);$$('.client-chip').forEach(x=>x.classList.toggle('active',String(x.dataset.client)===String(id)));if($('#analyticsClient'))$('#analyticsClient').value=id};
  $('#analyticsClient')?.addEventListener('change',e=>show(e.target.value));$$('.client-chip').forEach(b=>b.onclick=()=>show(b.dataset.client));
}
async function controlPage(){
  try{
    const d=await api('/api/control'),g=d.guide||{};
    $('#content').innerHTML=`<div class="page-head"><div><h1>Controllo Agenzia</h1><p>Rapporto automatico tra quantità di lavoro prevista e canone mensile.</p></div></div><div class="grid two-col"><div class="card"><div class="section-title"><h2>Carico / valore per cliente</h2><span>${d.clients?.length||0} analizzati</span></div><div class="list">${(d.clients||[]).map(c=>`<div class="list-row control-client"><div class="grow"><div class="strong">${esc(c.name)}</div><div class="small muted">${esc(c.summary||'Nessun servizio configurato')} · ${fmtEUR(c.monthly_value)}/mese</div><div class="progress"><i style="width:${Math.min(100,c.score)}%"></i></div></div><span class="badge ${c.risk==='Alto'?'danger':c.risk==='Medio'?'warn':'ok'}">${c.risk}</span></div>`).join('')||'<div class="empty">Configura i pacchetti cliente per ottenere l’analisi.</div>'}</div></div><div class="card"><div class="section-title"><h2>Indicatori</h2></div><div class="metric-row"><div class="metric"><b>${d.overdue||0}</b><span>incassi scaduti</span></div><div class="metric"><b>${d.packages30||0}</b><span>pacchetti entro 30 gg</span></div><div class="metric"><b>${d.openLeads||0}</b><span>lead aperti</span></div><div class="metric"><b>${d.clients?.length||0}</b><span>clienti attivi</span></div></div><div class="section-title" style="margin-top:22px"><h2>Gestione Social complessiva</h2></div><div class="metric-row"><div class="metric"><b>${d.social?.posts||0}</b><span>post/mese</span></div><div class="metric"><b>${d.social?.reels||0}</b><span>reel/mese</span></div><div class="metric"><b>${d.social?.stories||0}</b><span>storie/mese</span></div><div class="metric"><b>${d.social?.total||0}</b><span>contenuti/mese</span></div></div></div></div><div class="card control-guide" style="margin-top:16px"><div class="section-title"><div><h2>Come leggere Basso, Medio e Alto</h2><span>Indice Carico / Valore: più sale, più lavoro stai includendo rispetto al canone.</span></div></div><div class="guide-grid"><div class="guide-item"><span class="badge ok">Basso</span><strong>Rapporto sostenibile</strong><p>Fino a ${g.lowMax||3.5} punti di lavoro ogni 100 € di canone.</p></div><div class="guide-item"><span class="badge warn">Medio</span><strong>Da controllare</strong><p>Tra ${g.lowMax||3.5} e ${g.mediumMax||6} punti ogni 100 €. Verifica richieste extra e marginalità.</p></div><div class="guide-item"><span class="badge danger">Alto</span><strong>Possibile sottoprezzo</strong><p>Oltre ${g.mediumMax||6} punti ogni 100 €. Il pacchetto può essere troppo carico rispetto al prezzo.</p></div></div><div class="small muted" style="margin-top:16px">Pesi usati: Post = ${g.weights?.post||1} · Reel = ${g.weights?.reel||2} · Storia = ${g.weights?.story||0.25}. Gli altri servizi hanno pesi dedicati. È un indicatore gestionale, non un calcolo di ore.</div></div>`;
  }catch(e){pageLoadError('Controllo Agenzia',e)}
}
function pageLoadError(title,e){console.error(title,e);$('#content').innerHTML=`<div class="page-head"><div><h1>${esc(title)}</h1><p>Si è verificato un errore nel caricamento.</p></div></div><div class="card"><div class="notice danger"><strong>Errore:</strong> ${esc(e?.message||'Errore sconosciuto')}</div><button class="btn btn-primary" id="retryPage" style="margin-top:16px">Riprova</button></div>`;$('#retryPage').onclick=()=>navigate(state.page)}
async function settingsPage(){const d=await api('/api/settings');$('#content').innerHTML=`<div class="page-head"><div><h1>Impostazioni</h1><p>Identità del gestionale e dati EFFE predisposti per il futuro.</p></div></div><div class="card"><form id="settingsForm"><div class="form-grid">${fieldHtml('agency_name','Nome attività','text',d.agency_name||'EFFE Digital Strategy',1)}${fieldHtml('owner_name','Titolare','text',d.owner_name||'Francesco Fera')}${fieldHtml('email','Email','email',d.email||'')}${fieldHtml('phone','Telefono','text',d.phone||'')}${fieldHtml('vat','P.IVA','text',d.vat||'')}${fieldHtml('tax_code','Codice fiscale','text',d.tax_code||'')}${fieldHtml('iban','IBAN','text',d.iban||'',1)}${fieldHtml('address','Indirizzo','text',d.address||'',1)}</div><button class="btn btn-primary" style="margin-top:12px">Salva impostazioni</button></form></div>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();await api('/api/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});toast('Impostazioni salvate')}}
function modal(title,body,onSave,extra='',documentMode=false){const el=document.createElement('div');el.className='modal-backdrop';el.id='modal';el.innerHTML=`<div class="modal"><div class="modal-head no-print"><h3>${title}</h3><button class="xbtn" id="closeModal">×</button></div><div class="modal-body">${body}</div><div class="modal-foot no-print">${extra}<button class="btn btn-ghost" id="cancelModal">Chiudi</button>${onSave?'<button class="btn btn-primary" id="saveModal">Salva</button>':''}</div></div>`;document.body.appendChild(el);$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;if(onSave)$('#saveModal').onclick=onSave}
function closeModal(){$('#modal')?.remove()}
function toast(t){const x=document.createElement('div');x.className='toast';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),2800)}
function quickAdd(){const options=[['Cliente','clients'],['Lead','leads'],['Preventivo','quotes'],['Fattura','invoices'],['Pagamento','payments']];modal('Creazione rapida',`<div class="grid three-col">${options.map(([l,p])=>`<button class="btn btn-ghost quick" data-p="${p}" style="min-height:80px">${l}</button>`).join('')}</div>`,null);$$('.quick').forEach(b=>b.onclick=()=>{closeModal();navigate(b.dataset.p);setTimeout(()=>{if(b.dataset.p==='quotes')$('#newQuote')?.click();else if(b.dataset.p==='payments')$('#addPayment')?.click();else $('#addEntity')?.click()},250)})}
async function globalSearch(e){const q=e.target.value.trim();if(q.length<2)return;const d=await api('/api/search?q='+encodeURIComponent(q));modal(`Risultati per “${esc(q)}”`,`<div class="list">${(d.items||[]).map(x=>`<button class="list-row" style="width:100%;color:inherit;text-align:left" data-page="${x.page}"><div class="grow"><div class="strong">${esc(x.title)}</div><div class="small muted">${esc(x.subtitle||'')}</div></div><span class="badge info">${esc(x.type)}</span></button>`).join('')||'<div class="empty">Nessun risultato.</div>'}</div>`,null);$$('#modal [data-page]').forEach(b=>b.onclick=()=>{closeModal();navigate(b.dataset.page)})}
function debounce(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}}
window.addEventListener('hashchange',()=>{if(state.session?.authenticated)navigate(location.hash.slice(1)||'dashboard')});init();
